contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount, address spender) public {
        require(from != address(0));
        require(to != address(0));
        require(spender != address(0));

        // Setup: make msg.sender (i.e., address(this)) the spender by approving from.
        // We must have enough balance to perform the transfer, so use the owner's balance.
        // The owner is address(this) after construction in C.
        uint256 b = c.balanceOf(address(this));
        require(b >= amount);

        // Set allowance of this contract over from's tokens.
        c.approve(spender, 0);
        c.transferFrom(address(this), from, amount);
        c.approve(address(this), amount);
        c.transferFrom(from, address(this), amount);
        c.approve(spender, amount);

        // Record before allowance for the pair (from, spender)
        uint256 beforeAllowance = c.allowance(from, spender);

        // Perform the transferFrom as msg.sender (this contract).
        // preconditions checked by the contract: to != 0, from has enough balance, allowance sufficient.
        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After a successful call, the allowance must have decreased exactly by amount.
        uint256 afterAllowance = c.allowance(from, spender);

        assert(reverted || afterAllowance == beforeAllowance - amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount, address spender) public {
        require(to != address(0));
        require(spender != address(0));
        require(from != address(0));
        require(spender == address(this));

        // The test contract is the owner and initial holder of tokens.
        // Give `from` some tokens so the transferFrom can succeed.
        uint256 balance = c.balanceOf(address(this));
        require(balance >= amount);
        c.transfer(from, amount);

        // Set up allowance: `from` approves this contract (the spender) to spend `amount`.
        // Since only the allowance owner can call approve, and `from` is arbitrary,
        // we cannot call approve directly on behalf of `from`.
        // Instead, we use the fact that transferFrom checks allowance[from][msg.sender].
        // We must ensure allowance[from][address(this)] >= amount.
        // The contract does not provide a way to set arbitrary allowances,
        // so we rely on the initial state: allowances may be zero.
        // To make the call succeed, we need allowance[from][spender] >= amount.
        // We cannot set it without being `from`.
        // Therefore, we restrict to cases where `from` is this contract, so that
        // approve works with msg.sender == address(this).
        // However, then the transferFrom would transfer from this contract to `to`,
        // decreasing allowance[address(this)][spender].
        // We can set that allowance by calling c.approve(spender, amount).
        require(from == address(this));

        // Now approve spender to spend amount from this contract.
        c.approve(spender, amount);

        uint256 beforeAllowance = c.allowance(from, spender);
        require(beforeAllowance >= amount);

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(from, spender);

        assert(reverted || afterAllowance == beforeAllowance - amount);
    }

    receive() external payable {}
}

