contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public {
        require(to != address(0));
        require(from != address(0));

        // Set up: give `from` some balance by transferring from the test contract.
        // The constructor gave the test contract totalDistributed tokens.
        c.transfer(from, amount);

        // Approve the test contract as spender on behalf of `from`.
        // The test contract is msg.sender for c; `from` is an arbitrary parameter.
        // We cannot call approve as `from`, but we can still exercise transferFrom
        // with a non-zero allowance only if `from` equals the test contract.
        // To avoid an always-reverting setup, use from = address(this).
        // But `from` is a parameter; require it to be address(this) would be a
        // parameter precondition, which is allowed.
        // However, to keep a general rule, use from = address(this) via require.
        require(from == address(this));

        c.approve(address(this), amount);

        uint256 beforeAllowance = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(from, address(this));

        assert(reverted || afterAllowance == beforeAllowance - amount);
    }

    receive() external payable {}
}

