contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 _value) public payable {
        uint256 preTotalDistributed = c.totalDistributed();
        uint256 ownerBalance = c.balanceOf(address(this));
        require(_value <= ownerBalance);

        bool reverted;
        try c.burn(_value) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            uint256 postTotalDistributed = c.totalDistributed();
            assert(postTotalDistributed == preTotalDistributed - _value);
        } else {
            assert(c.totalDistributed() == preTotalDistributed);
        }
    }
}

